// ================== ELIGE AQUÍ EL AMBIENTE ==================
//  "staging"    → pruebas  (secretos CREDIVIVA_*_STAGING)
//  "production" → clientes reales (secretos CREDIVIVA_*_PRODUCTION)
const AMBIENTE = "staging";
// País de operación (Panamá es el único activo en esta fase)
const PAIS = "PA";
// ============================================================
if (AMBIENTE !== "staging" && AMBIENTE !== "production") {
  throw new Error("AMBIENTE debe ser staging o production");
}
$memory.set("cv_ambiente", AMBIENTE);
$memory.set("cv_countryCode", PAIS);
